package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.verify;

/**
 * Unit tests for TokenBuffer.writeNumber(BigInteger v)
 */
public class TokenBuffer_writeNumber_TriageGen1Test {

    private TokenBuffer tokenBuffer;
    private ObjectMapper mapper;

    @Mock
    private JsonParser mockParser;

    @Mock
    private DeserializationContext mockContext;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        mapper = new ObjectMapper();
        // Using the constructor that takes an ObjectCodec
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumber_WithNull() throws IOException {
        // This tests the branch where v == null
        tokenBuffer.writeNumber((BigInteger) null);

        // Verification: Since TokenBuffer is a buffer, we verify the state by 
        // checking if the first token is VALUE_NULL
        Assert.assertEquals(JsonToken.VALUE_NULL, tokenBuffer.firstToken());
    }

    @Test
    public void testWriteNumber_WithValidBigInteger() throws IOException {
        // This tests the branch where v != null
        BigInteger value = new BigInteger("123456789012345678901234567890");

        tokenBuffer.writeNumber(value);

        // Verification: First token should be VALUE_NUMBER_INT
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, tokenBuffer.firstToken());

        // To verify the actual value, we can simulate serializing it to a string
        // or checking the parser behavior.
        String json = tokenBuffer.toString();
        Assert.assertTrue(json.contains(value.toString()));
    }

    @Test
    public void testWriteNumber_WithZero() throws IOException {
        BigInteger value = BigInteger.ZERO;
        tokenBuffer.writeNumber(value);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, tokenBuffer.firstToken());
        Assert.assertTrue(tokenBuffer.toString().contains("0"));
    }

    @Test
    public void testWriteNumber_WithNegative() throws IOException {
        BigInteger value = new BigInteger("-987654321");
        tokenBuffer.writeNumber(value);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, tokenBuffer.firstToken());
        Assert.assertTrue(tokenBuffer.toString().contains("-987654321"));
    }

    @Test
    public void testWriteNumber_UsingParserConstructor() throws IOException {
        // Testing coverage for different constructors to ensure environment is stable
        TokenBuffer bufferWithParser = new TokenBuffer(mockParser, mockContext);
        bufferWithParser.writeNumber(BigInteger.ONE);
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, bufferWithParser.firstToken());
    }
}
